mapper.update:
UPDATE bike_vehicle
SET status=2, stock_out_time=NULL, current_customer_id=NULL, current_order_no=NULL
WHERE id=#{vehicleId}
  AND status=3
  AND current_customer_id=#{customerId}
  AND current_order_no=#{orderNo}
  AND NOT EXISTS (
      SELECT 1 FROM bike_stock_out_record newer
      WHERE newer.vehicle_id=#{vehicleId}
        AND newer.status='COMPLETED'
        AND newer.id > #{stockOutRecordId}
  )

