WHERE 1=1 AND EXISTS(SELECT 1 FROM bike_agent_model_access access JOIN bike_agent a ON a.id=access.agent_id AND a.status='ENABLED' JOIN bike_product_model m ON m.id=access.model_id AND m.enabled=1 WHERE access.agent_id=#{agentId} AND access.model_id=p.model_id AND access.enabled=1)
AND p.model_id=#{modelId}
AND p.warehouse_id=#{warehouseId}
